    // 如果太短（< 1 秒），只做轻量增强避免误伤
    let minSamplesForSpectral = Int(sampleRate * 1.0)
    if result.count >= minSamplesForSpectral {
        enhanceInPlace(&result, sampleRate: sampleRate)
    } else {
        realtimeEnhanceInPlace(&result, sampleRate: sampleRate)
    }

